package master

import (
	"net"
	"net/http"
	"strings"
	"text/template"
)

// The install script is fetched over TLS pinned with curl --pinnedpubkey, so
// the checksums it embeds can be trusted to verify the downloaded binary.
var installTpl = template.Must(template.New("install").Parse(`#!/bin/sh
# coremon agent installer - generated by the master at {{.URL}}
set -eu

MASTER="{{.URL}}"
PIN="{{.Pin}}"
SHA_AMD64="{{.SHAAmd64}}"
SHA_ARM64="{{.SHAArm64}}"
TOKEN=""

die() { echo "coremon: $*" >&2; exit 1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --token) TOKEN="${2:-}"; shift 2 ;;
    *) die "unknown argument: $1" ;;
  esac
done

[ "$(id -u)" = "0" ] || die "must run as root"
command -v systemctl >/dev/null 2>&1 || die "systemd is required"
command -v curl >/dev/null 2>&1 || die "curl is required (apt-get install -y curl)"
command -v sha256sum >/dev/null 2>&1 || die "sha256sum is required"

case "$TOKEN" in ""|*[!a-f0-9]*) [ -f /var/lib/coremon/identity.json ] || die "a valid --token is required" ;; esac

case "$(uname -m)" in
  x86_64|amd64) ARCH=amd64; SHA="$SHA_AMD64" ;;
  aarch64|arm64) ARCH=arm64; SHA="$SHA_ARM64" ;;
  *) die "unsupported architecture: $(uname -m)" ;;
esac
[ -n "$SHA" ] || die "the master has no agent build for linux-$ARCH"

TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
echo "coremon: downloading agent (linux-$ARCH)"
curl -fsSL -k --pinnedpubkey "sha256//$PIN" -o "$TMP" "$MASTER/dl/agent/linux-$ARCH"
echo "$SHA  $TMP" | sha256sum -c - >/dev/null 2>&1 || die "checksum mismatch - aborting"
install -m 0755 "$TMP" /usr/local/bin/coremon-agent

mkdir -p /etc/coremon /var/lib/coremon
chmod 700 /etc/coremon /var/lib/coremon

if [ -f /var/lib/coremon/identity.json ]; then
  echo "coremon: already enrolled - updating binary and service only"
else
  umask 077
  cat > /etc/coremon/agent.json <<EOF
{
  "master_url": "$MASTER",
  "master_pin": "$PIN",
  "token": "$TOKEN"
}
EOF
fi

cat > /etc/systemd/system/coremon-agent.service <<'EOF'
[Unit]
Description=coremon agent
Wants=network-online.target
After=network-online.target

[Service]
ExecStart=/usr/local/bin/coremon-agent
Restart=on-failure
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable coremon-agent.service >/dev/null 2>&1
systemctl restart coremon-agent.service
echo "coremon: agent installed and started."
echo "coremon: approve this system in the master UI: $MASTER"
`))

func (s *Server) baseURL(r *http.Request) string {
	s.st.mu.Lock()
	u := s.st.st.Settings.MasterURL
	s.st.mu.Unlock()
	if u != "" {
		return strings.TrimRight(u, "/")
	}
	return s.derivedURL(r)
}

// derivedURL guesses the agent-facing URL from the request: the host the
// browser used, with the agents' port. Agents never use the website-only
// port 443 or a reverse proxy, so the website port can change freely.
func (s *Server) derivedURL(r *http.Request) string {
	host := r.Host
	if h, _, err := net.SplitHostPort(r.Host); err == nil {
		host = h
	}
	host = strings.Trim(host, "[]")
	return "https://" + net.JoinHostPort(host, s.agentPort())
}

func (s *Server) handleInstallScript(w http.ResponseWriter, r *http.Request) {
	latest := s.repo.coreLatest()
	data := struct{ URL, Pin, SHAAmd64, SHAArm64 string }{URL: s.baseURL(r), Pin: s.pin}
	if e := s.repo.find("core", latest, "linux", "amd64"); e != nil {
		data.SHAAmd64 = e.SHA256
	}
	if e := s.repo.find("core", latest, "linux", "arm64"); e != nil {
		data.SHAArm64 = e.SHA256
	}
	w.Header().Set("Content-Type", "text/x-shellscript; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_ = installTpl.Execute(w, data)
}

func (s *Server) installCommand(r *http.Request, token string) string {
	return "curl -fsSLk --pinnedpubkey 'sha256//" + s.pin + "' " + s.baseURL(r) + "/install.sh | sh -s -- --token " + token
}
